import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cstdint>

#define TILE_OH 8
#define TILE_OW 8
__global__ void conv_transpose2d_gather_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    const long long total,
    const int batch,
    const int C_in,
    const int H_in,
    const int W_in,
    const int C_out,
    const int H_out,
    const int W_out,
    const int kH,
    const int kW,
    const int stride_h,
    const int stride_w,
    const int pad_h,
    const int pad_w,
    const int dil_h,
    const int dil_w,
    const int groups,
    const int tiles_h,
    const int tiles_w) {
  extern __shared__ float s_in[];
  (void)total;
  (void)batch;
  const int C_out_pg = C_out / groups;
  const int C_in_pg = C_in / groups;
  const long long in_hw = (long long)H_in * W_in;
  const long long out_hw = (long long)H_out * W_out;
  long long b = blockIdx.x;
  const int tw = (int)(b % tiles_w); b /= tiles_w;
  const int th = (int)(b % tiles_h); b /= tiles_h;
  const int g = (int)(b % groups);
  const int n = (int)(b / groups);
  const int oh0 = th * TILE_OH;
  const int ow0 = tw * TILE_OW;
  // Bounding box of the input region required by this output tile.
  const int num_h_min = oh0 + pad_h - (kH - 1) * dil_h;
  const int num_h_max = oh0 + TILE_OH - 1 + pad_h;
  const int num_w_min = ow0 + pad_w - (kW - 1) * dil_w;
  const int num_w_max = ow0 + TILE_OW - 1 + pad_w;
  const int ih_min = (num_h_min > 0) ? (num_h_min / stride_h) : 0;
  const int iw_min = (num_w_min > 0) ? (num_w_min / stride_w) : 0;
  int ih_max = (num_h_max > 0) ? (num_h_max / stride_h) : 0;
  int iw_max = (num_w_max > 0) ? (num_w_max / stride_w) : 0;
  ih_max = min(ih_max, H_in - 1);
  iw_max = min(iw_max, W_in - 1);
  const int sh = ih_max - ih_min + 1;
  const int sw = iw_max - iw_min + 1;
  const int ic0 = g * C_in_pg;
  const float* x_base = input + ((long long)n * C_in + ic0) * in_hw;
  // Cooperatively stage the reusable input tile into shared memory.
  const int tid = threadIdx.x;
  const int nthreads = blockDim.x;
  const int stage_total = C_in_pg * sh * sw;
  for (int s = tid; s < stage_total; s += nthreads) {
    const int siw = s % sw;
    const int t2 = s / sw;
    const int sih = t2 % sh;
    const int ic = t2 / sh;
    s_in[s] = __ldg(x_base + (long long)ic * in_hw +
                    (long long)(ih_min + sih) * W_in + (iw_min + siw));
  }
  __syncthreads();
  const int SP = TILE_OH * TILE_OW;
  const long long w_ic_stride = (long long)C_out_pg * kH * kW;
  const long long w_oc_stride = (long long)kH * kW;
  const int oc_chunks = (C_out_pg + 1) / 2;
  // Register-block two output channels per spatial site to cut register pressure and lift occupancy.
  for (int linear = tid; linear < oc_chunks * SP; linear += nthreads) {
    const int oc_chunk = linear / SP;
    const int sp = linear - oc_chunk * SP;
    const int oh = oh0 + sp / TILE_OW;
    const int ow = ow0 + sp % TILE_OW;
    if (oh >= H_out || ow >= W_out) continue;
    const int oc_local0 = oc_chunk * 2;
    const int oc0 = g * C_out_pg + oc_local0;
    const bool full_oc = (oc_local0 + 2 <= C_out_pg);
    float acc[2];
    if (full_oc) {
      const float b0 = (bias != nullptr) ? __ldg(bias + oc0 + 0) : 0.0f;
      const float b1 = (bias != nullptr) ? __ldg(bias + oc0 + 1) : 0.0f;
      acc[0] = b0; acc[1] = b1;
    } else {
#pragma unroll
      for (int j = 0; j < 2; ++j) {
        acc[j] = (bias != nullptr && oc_local0 + j < C_out_pg) ? __ldg(bias + oc0 + j) : 0.0f;
      }
    }
    const float* w_base =
        weight + ((long long)ic0 * C_out_pg + oc_local0) * kH * kW;
    for (int kh = 0; kh < kH; ++kh) {
      const int num_h = oh + pad_h - kh * dil_h;
      if (num_h < 0) continue;
      if ((num_h % stride_h) != 0) continue;
      const int sih = num_h / stride_h - ih_min;
      if (sih < 0 || sih >= sh) continue;
      for (int kw = 0; kw < kW; ++kw) {
        const int num_w = ow + pad_w - kw * dil_w;
        if (num_w < 0) continue;
        if ((num_w % stride_w) != 0) continue;
        const int siw = num_w / stride_w - iw_min;
        if (siw < 0 || siw >= sw) continue;
        const float* s_ptr = s_in + (sih * sw + siw);
        const float* w_ptr = w_base + (kh * kW + kw);
        for (int ic = 0; ic < C_in_pg; ++ic) {
          const float x = s_ptr[ic * sh * sw];
          const float* w_ic = w_ptr + (long long)ic * w_ic_stride;
          if (full_oc) {
            acc[0] += x * __ldg(w_ic + 0 * w_oc_stride);
            acc[1] += x * __ldg(w_ic + 1 * w_oc_stride);
          } else {
#pragma unroll
            for (int j = 0; j < 2; ++j) {
              if (oc_local0 + j < C_out_pg) {
                acc[j] += x * __ldg(w_ic + (long long)j * w_oc_stride);
              }
            }
          }
        }
      }
    }
    const long long out_base =
        ((long long)n * C_out + oc0) * out_hw + (long long)oh * W_out + ow;
    if (full_oc) {
      output[out_base + 0 * out_hw] = acc[0];
      output[out_base + 1 * out_hw] = acc[1];
    } else {
#pragma unroll
      for (int j = 0; j < 2; ++j) {
        if (oc_local0 + j < C_out_pg) {
          output[out_base + (long long)j * out_hw] = acc[j];
        }
      }
    }
  }
}

torch::Tensor conv_transpose2d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    const c10::optional<torch::Tensor>& bias,
    int64_t stride_h,
    int64_t stride_w,
    int64_t pad_h,
    int64_t pad_w,
    int64_t dil_h,
    int64_t dil_w,
    int64_t groups) {
  TORCH_CHECK(input.is_cuda(), "input must be CUDA");
  TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
  TORCH_CHECK(input.scalar_type() == torch::kFloat32, "input must be float32");
  TORCH_CHECK(weight.scalar_type() == torch::kFloat32, "weight must be float32");
  TORCH_CHECK(input.dim() == 4, "input must be NCHW");
  TORCH_CHECK(weight.dim() == 4, "weight must be (C_in, C_out/groups, kH, kW)");
  TORCH_CHECK(stride_h > 0 && stride_w > 0, "stride must be positive");
  TORCH_CHECK(dil_h > 0 && dil_w > 0, "dilation must be positive");
  TORCH_CHECK(groups > 0, "groups must be positive");

  const int64_t batch = input.size(0);
  const int64_t C_in = input.size(1);
  const int64_t H_in = input.size(2);
  const int64_t W_in = input.size(3);

  const int64_t kH = weight.size(2);
  const int64_t kW = weight.size(3);
  const int64_t C_out_pg = weight.size(1);
  TORCH_CHECK(weight.size(0) == C_in, "weight in_channels mismatch");
  TORCH_CHECK(C_in % groups == 0, "C_in must be divisible by groups");
  const int64_t C_out = C_out_pg * groups;

  const int64_t H_out = (H_in - 1) * stride_h - 2 * pad_h + dil_h * (kH - 1) + 1;
  const int64_t W_out = (W_in - 1) * stride_w - 2 * pad_w + dil_w * (kW - 1) + 1;
  TORCH_CHECK(H_out > 0 && W_out > 0, "invalid output size");
  TORCH_CHECK(H_in < INT32_MAX && W_in < INT32_MAX && H_out < INT32_MAX && W_out < INT32_MAX,
              "tensor too large for int32 coordinates");

  auto input_c = input.contiguous();
  auto weight_c = weight.contiguous();

  const bool has_bias = bias.has_value();
  torch::Tensor bias_c;
  const float* bias_ptr = nullptr;
  if (has_bias) {
    bias_c = bias->contiguous();
    TORCH_CHECK(bias_c.is_cuda(), "bias must be CUDA");
    TORCH_CHECK(bias_c.scalar_type() == torch::kFloat32, "bias must be float32");
    TORCH_CHECK(bias_c.numel() == C_out, "bias has wrong shape");
    bias_ptr = bias_c.data_ptr<float>();
  }

  auto output = torch::empty({batch, C_out, H_out, W_out}, input_c.options());
  const long long total = (long long)batch * C_out * H_out * W_out;
  if (total == 0) return output;

  const int threads = 256;
  const int tiles_h = (int)((H_out + TILE_OH - 1) / TILE_OH);
  const int tiles_w = (int)((W_out + TILE_OW - 1) / TILE_OW);
  const long long blocks_ll = (long long)batch * groups * tiles_h * tiles_w;
  TORCH_CHECK(blocks_ll <= 2147483647LL, "grid too large");
  const unsigned int blocks = (unsigned int)blocks_ll;
  const int span_h = (TILE_OH - 1) + (int)((kH - 1) * dil_h);
  const int span_w = (TILE_OW - 1) + (int)((kW - 1) * dil_w);
  const int smem_h = (int)std::min<long long>(span_h / stride_h + 2, H_in);
  const int smem_w = (int)std::min<long long>(span_w / stride_w + 2, W_in);
  const size_t smem_bytes =
      (size_t)(C_in / groups) * (size_t)smem_h * (size_t)smem_w * sizeof(float);
  if (smem_bytes > 48 * 1024) {
    static int max_smem = -1;
    if (max_smem < 0) {
      cudaDeviceProp prop;
      C10_CUDA_CHECK(cudaGetDeviceProperties(&prop, input.get_device()));
      max_smem = (int)prop.sharedMemPerBlockOptin;
    }
    TORCH_CHECK((int)smem_bytes <= max_smem, "shared memory tile too large");
    static bool attr_set = false;
    if (!attr_set) {
      C10_CUDA_CHECK(cudaFuncSetAttribute(
          conv_transpose2d_gather_kernel,
          cudaFuncAttributeMaxDynamicSharedMemorySize, max_smem));
      attr_set = true;
    }
  }
  cudaStream_t stream = at::cuda::getCurrentCUDAStream();
  conv_transpose2d_gather_kernel<<<blocks, threads, smem_bytes, stream>>>(
      input_c.data_ptr<float>(),
      weight_c.data_ptr<float>(),
      bias_ptr,
      output.data_ptr<float>(),
      total,
      (int)batch,
      (int)C_in,
      (int)H_in,
      (int)W_in,
      (int)C_out,
      (int)H_out,
      (int)W_out,
      (int)kH,
      (int)kW,
      (int)stride_h,
      (int)stride_w,
      (int)pad_h,
      (int)pad_w,
      (int)dil_h,
      (int)dil_w,
      (int)groups,
      tiles_h,
      tiles_w);
  C10_CUDA_KERNEL_LAUNCH_CHECK();
  return output;
}
"""

_cpp_src = r"""
torch::Tensor conv_transpose2d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    const c10::optional<torch::Tensor>& bias,
    int64_t stride_h,
    int64_t stride_w,
    int64_t pad_h,
    int64_t pad_w,
    int64_t dil_h,
    int64_t dil_w,
    int64_t groups);
"""

_ext = load_inline(
    name="custom_conv_transpose2d_gather",
    cpp_sources=[_cpp_src],
    cuda_sources=[_cuda_src],
    functions=["conv_transpose2d_forward"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        kernel_size: tuple,
        stride: tuple = (1, 1),
        padding: tuple = (0, 0),
        dilation: tuple = (1, 1),
        groups: int = 1,
        bias: bool = False,
    ):
        super(ModelNew, self).__init__()
        self.stride_h, self.stride_w = int(stride[0]), int(stride[1])
        self.pad_h, self.pad_w = int(padding[0]), int(padding[1])
        self.dil_h, self.dil_w = int(dilation[0]), int(dilation[1])
        self.groups = int(groups)

        # Parameter container only; forward uses the custom CUDA kernel above.
        self.conv_transpose2d = nn.ConvTranspose2d(
            in_channels,
            out_channels,
            kernel_size,
            stride=stride,
            padding=padding,
            dilation=dilation,
            groups=groups,
            bias=bias,
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return _ext.conv_transpose2d_forward(
            x,
            self.conv_transpose2d.weight,
            self.conv_transpose2d.bias,
            self.stride_h,
            self.stride_w,
            self.pad_h,
            self.pad_w,
            self.dil_h,
            self.dil_w,
            self.groups,
        )

