torch::Tensor conv_transpose2d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    const c10::optional<torch::Tensor>& bias,
    int64_t stride_h,
    int64_t stride_w,
    int64_t pad_h,
    int64_t pad_w,
    int64_t dil_h,
    int64_t dil_w,
    int64_t groups) {
