  TORCH_CHECK(C_in % groups == 0, "C_in must be divisible by groups");
  const int64_t C_out = C_out_pg * groups;

  const int64_t H_out = (H_in - 1) * stride_h - 2 * pad_h + dil_h * (kH - 1) + 1;
  const int64_t W_out = (W_in - 1) * stride_w - 2 * pad_w + dil_w * (kW - 1) + 1;
  TORCH_CHECK(H_out > 0 && W_out > 0, "invalid output size");
  TORCH_CHECK(H_in < INT32_MAX && W_in < INT32_MAX && H_out < INT32_MAX && W_out < INT32_MAX,
              "tensor too large for int32 coordinates");

  auto input_c = input.contiguous();
  auto weight_c = weight.contiguous();

